<template>
  <main class="health-experience health-detail"><div class="health-shell">
    <nav class="crumbs"><NuxtLink to="/health">Health</NuxtLink><span>›</span><NuxtLink to="/health/services">Health Checkups</NuxtLink><span>›</span><span>{{ detail?.service.title || 'Service' }}</span></nav>
    <div v-if="loading" class="health-state" role="status">Loading care details...</div><div v-else-if="error" class="health-state health-error" role="alert">{{ error }} <button @click="load">Try again</button></div>
    <div v-else-if="detail" class="health-columns">
      <div><section class="health-panel service-description"><h1>{{ detail.service.title }}</h1><p class="lead">{{ detail.service.summary }}</p>
        <div class="tags"><span>{{ detail.service.cityName }}</span><span>{{ detail.service.durationLabel }}</span><span>{{ detail.service.supportLanguages }} support</span><span>Appointment required</span></div>
        <h2>Service highlights</h2><div class="inclusions"><article v-for="(item,index) in detail.inclusions.filter(item => item.phase === 'INCLUDED')" :key="'highlight-'+index"><small>{{ String(index+1).padStart(2,'0') }}</small><h3>{{ item.title }}</h3><p>{{ item.description }}</p></article></div>
        <section v-if="detail.contentGroups?.length" class="service-content"><h2>What's included</h2><div v-for="(group,groupIndex) in detail.contentGroups" :key="'content-group-'+groupIndex" class="content-table" :class="{ 'first-table': groupIndex === 0, 'last-table': groupIndex === detail.contentGroups.length - 1 }"><div class="content-header"><div class="content-group-title">{{ group.title }}</div><div class="content-gender-header male">Male</div><div class="content-gender-header female">Female</div></div><div v-for="(item,itemIndex) in group.items" :key="'content-item-'+itemIndex" class="content-row"><div class="content-item-title">{{ item.title }}</div><div class="content-gender-cell"><span v-if="item.maleSupported" class="gender-dot male" role="img" aria-label="Male applicable"></span></div><div class="content-gender-cell"><span v-if="item.femaleSupported" class="gender-dot female" role="img" aria-label="Female applicable"></span></div></div></div></section>
        <div v-for="(item,index) in detail.inclusions.filter(item => ['REPORT','POLICY'].includes(item.phase))" :key="'policy-'+index" class="policy"><h2>{{ item.phase === 'POLICY' ? 'Cancellation policy' : 'Report' }}</h2><p>{{ item.description }}</p></div>
        <div v-for="(item,index) in detail.inclusions.filter(item => item.phase === 'CUSTOM')" :key="'custom-'+index" class="policy"><h2>{{ item.title }}</h2><p>{{ item.description }}</p></div>
      </section>
      <section class="health-panel provider-information"><h2>Provider information</h2><template v-if="detail.providers.length"><div v-for="provider in detail.providers" :key="provider.providerName"><strong>{{ provider.providerName }}</strong><p>{{ provider.facilityType }} · {{ provider.cityName }} · {{ provider.supportedLanguages }}</p><p v-if="provider.address">{{ provider.address }}</p></div></template><p v-else>Provider details are confirmed by the Care Team.</p></section></div>
      <aside class="booking-rail"><div class="health-rail"><div class="health-form"><label>Preferred date<input v-model="date" type="date" :min="minimumDate"></label><label>Preferred time<select v-model="time"><option>Morning</option><option>Afternoon</option><option>Flexible</option></select></label></div><div class="price"><strong>From</strong><strong>US${{ Number(detail.service.startingPrice).toFixed(2) }}</strong></div><button type="button" class="health-button" :disabled="!date" @click="request">Request Appointment</button><p class="health-notice">Usually confirmed by the Care Team after provider availability is checked.</p></div>
        <div class="health-rail coordinator"><span class="email-icon"><img src="/images/health/design/email.svg" alt=""></span><div><h3>Not sure this is right for you?</h3><p>Tell us what you are looking for and a Care Coordinator will help route the request.</p></div><NuxtLink to="/health/concierge">Talk to Care Coordinator <img src="/images/health/design/arrow-right.svg" alt=""></NuxtLink></div>
      </aside>
    </div>
  </div></main>
</template>
<script setup lang="ts">
const route = useRoute(), health = useHealthCare(), detail = ref<import('~/composables/useHealthCare').HealthServiceDetail>(), loading = ref(true), error = ref(''), date = ref(''), time = ref('Morning')
async function load(){ loading.value=true;error.value='';try { detail.value = await health.getService(String(route.params.serviceCode)) } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load this service.' } finally { loading.value = false } }
onMounted(load)
const minimumDate = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit' }).format(new Date())
const request = async () => { await navigateTo('/health/appointments/new?serviceCode='+encodeURIComponent(String(route.params.serviceCode))+'&date='+encodeURIComponent(date.value)+'&time='+encodeURIComponent(time.value)) }
useLvyvSeo({ title: 'Care Service | LVYV Care', description: 'Review service highlights before requesting a planned healthcare appointment.', path: '/health/services/'+route.params.serviceCode })
</script>
