-top:12px}.booking-rail{position:sticky;top:100px;display:grid;gap:20px}.price{border-top:1px solid #ddd;margin:32px 0 40px;padding-top:24px;display:flex;justify-content:space-between;gap:12px;font-size:16px;color:#242424}.price strong:last-child{font-size:22px;color:#203d33}.booking-rail .health-button{width:100%;font-weight:500}.booking-rail .health-notice{margin:30px -16px 0}.coordinator{display:grid;grid-template-columns:68px 1fr;gap:12px 30px}.email-icon{display:grid;place-items:center;width:68px;height:68px;background:#cff380b3;border-radius:99px}.email-icon img{width:36px;height:36px}.coordinator h3{font:500 16px/24px Inter,sans-serif;color:#105446;margin:0 0 12px}.coordinator p{font-size:14px;line-height:20px;color:#0008}.coordinator a{grid-column:1/-1;display:flex;gap:10px;justify-content:center;align-items:center;color:#698e4e;text-decoration:none;font-size:16px}.coordinator a img{width:24px;height:24px}
